-- Entity: the interface (ports and generics)
entity adder is
    generic (
        WIDTH : natural := 8    -- parameterizable
    );
    port (
        a    : in  std_logic_vector(WIDTH-1 downto 0);
        b    : in  std_logic_vector(WIDTH-1 downto 0);
        cin  : in  std_logic;
        sum  : out std_logic_vector(WIDTH-1 downto 0);
        cout : out std_logic
    );
end entity adder;

-- Architecture: the implementation
architecture rtl of adder is
    signal result : unsigned(WIDTH downto 0);
begin
    result <= ('0' & unsigned(a)) + ('0' & unsigned(b)) + ("" & cin);
    sum  <= std_logic_vector(result(WIDTH-1 downto 0));
    cout <= result(WIDTH);
end architecture rtl;

-- Structural architecture (component instantiation)
entity top is
