architecture rtl of concurrent_demo is
    signal a, b, c, y : std_logic;
    signal sel : std_logic_vector(1 downto 0);
begin

    -- Simple concurrent signal assignment
    y <= a and b;
    y <= a or b or c;

    -- Conditional assignment (when-else)
    y <= a when sel = "00" else
         b when sel = "01" else
         c when sel = "10" else
         '0';

    -- Selected signal assignment (with-select)
    with sel select
        y <= a when "00",
             b when "01",
             c when "10",
             '0' when others;

    -- Generate (loop in hardware)
    gen_reg : for i in 0 to 7 generate
        -- creates 8 instances
    end generate;

    -- Process statement (concurrent block, sequential inside)
    proc_comb : process(a, b, c)
    begin
        -- defaults first (prevent latches!)
        y <= '0';
        if a = '1' then
            y <= b;
        elsif b = '1' then
            y <= c;
        end if;
    end process;

    -- Clocked process
    proc_clk : process(clk, rst_n)
    begin
        if rst_n = '0' then    -- async reset
            y <= '0';
        elsif rising_edge(clk) then  -- sync logic
            y <= a and b;
        end if;
    end process;

end architecture;
