-- 2-process FSM (recommended style)
architecture rtl of fsm_demo is
    type state_t is (idle, run, done);
    signal state, next_state : state_t;
begin

    -- PROCESS 1: State register (clocked)
    state_reg : process(clk, rst_n)
    begin
        if rst_n = '0' then
            state <= idle;
        elsif rising_edge(clk) then
            state <= next_state;
        end if;
    end process;

    -- PROCESS 2: Next state + outputs (combinational)
    comb : process(state, start, done_flag)
    begin
        -- Default assignments (PREVENT LATCHES!)
        next_state <= state;
        busy       <= '0';
        result_en  <= '0';

        case state is
            when idle =>
                if start = '1' then
                    next_state <= run;
                end if;
            when run =>
                busy <= '1';
                if done_flag = '1' then
                    next_state <= done;
                end if;
            when done =>
                result_en  <= '1';
                next_state <= idle;
            when others =>
                next_state <= idle;
        end case;
    end process;

end architecture;
